<?php
require_once 'functions.php';require_role(['admin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'save';if($a==='delete'){if((int)$_POST['id']=== (int)user()['id_user']){flash('Tidak bisa menghapus akun sendiri.','error');go('pengguna.php');}$pdo->prepare("DELETE FROM users WHERE id_user=?")->execute([(int)$_POST['id']]);flash('Pengguna dihapus.');go('pengguna.php');}
try{$name=trim($_POST['nama']);$username=trim($_POST['username']);$role=$_POST['role'];$id=(int)($_POST['id']??0);if($id){$pdo->prepare("UPDATE users SET nama=?,username=?,role=? WHERE id_user=?")->execute([$name,$username,$role,$id]);}else{$pw=$_POST['password']??'';if(strlen($pw)<6)throw new Exception('Password minimal 6 karakter.');$pdo->prepare("INSERT INTO users(nama,username,password,role) VALUES(?,?,?,?)")->execute([$name,$username,password_hash($pw,PASSWORD_DEFAULT),$role]);}flash('Data pengguna disimpan.');}catch(Throwable $e){flash('Gagal menyimpan: '.$e->getMessage(),'error');}go('pengguna.php');}
$rows=$pdo->query("SELECT id_user,nama,username,role,created_at FROM users ORDER BY id_user DESC")->fetchAll();layout_header('Pengguna');
?>
<div class="page-title"><div><span class="eyebrow">AKSES SISTEM</span><h1>Kelola pengguna</h1></div></div><div class="panel"><h3>Tambah akun</h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><div class="form-grid"><div><label>Nama</label><input name="nama" required></div><div><label>Username</label><input name="username" required></div><div><label>Password</label><input type="password" name="password" required minlength="6"></div><div><label>Role</label><select name="role"><option value="kasir">Kasir</option><option value="pelanggan">Pelanggan</option><option value="admin">Admin</option></select></div></div><button class="btn btn-primary">Tambah Pengguna</button></form></div><div class="section-head"><h2>Daftar pengguna</h2></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama'])?></td><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td><td><?=e($r['created_at'])?></td><td><?php if($r['id_user']!=user()['id_user']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id_user']?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus pengguna ini?">Hapus</button></form><?php else:?><small>Akun aktif</small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php layout_footer(); ?>
